import hashlib,json
from pathlib import Path
from datetime import datetime,timezone
base=Path(__file__).resolve().parent;root=base.parents[3];folder=base/'cas-overlap-review';inputs=json.loads((folder/'inputs.json').read_text(encoding='utf-8'))
notes=[
('Fulfillment read projection','Row-image provenance calls pass the exact selected row to the same V926/V933 archive-root/ancestry function used by the Main id wrapper, avoiding a redundant lookup; legacy_id/import_run direct exclusions remain. Adds explicit metadataIncluded=false continuation preserving exact total and allowedActions/capabilities. Reuses unchanged ProcurementDeliveryDifference formula after paging only when no difference filter/sort; warehouse product/request LATERAL remains pre-selection for a real keyword and moves after page otherwise. TableQuery whitelist has no product/request/segment field filter or sort; execution_segment_codes is search-only and not in ROW_COLUMNS. Export retains full pre-selection enrichment. All Main department/status/date/warehouse/owner scopes, BOM/kit progress, identities and action access remain.'),
('Purchase approval predicate','Replaces eager whole-company PENDING/latest REJECTED ID materialization with correlated EXISTS on immutable ProcurementOrderApprovalRead. Same order_type, request_type=ORDER/status; latest REJECTED rejects any higher attempt. PENDING/REJECTED lifecycle and IN_PROGRESS physical-or-financial qualification retained, including pending finance on closed physical execution and stopped exclusion for physical branch. Existing owner ACL/header/commercial quantity/source rules and all writes outside this predicate unchanged.'),
('Sales row provenance','Only eight id-based imported-document checks become exact row-image calls for selected sales orders/items/shipment drafts. Native direct legacy exclusions, draft status/rejected/deleted guards, source availability expression, owner scope, delivery-plan and all exact numeric business calculations remain unchanged. V926 id wrapper ultimately invokes same row function.'),
('Sales report provenance','Only sales order/item provenance lookup form changes to row-image equivalent. Pending qty and proportional amount expressions, owner/client/currency grouping and all filters are exact Main unchanged.'),
('Subcontract approval/provenance','Same SQL PENDING/latest-REJECTED EXISTS equivalence as purchase; IN_PROGRESS retains physical unclosed-approved or live finance task. Source-lock and source-read archive lookup reuses selected row; sorted IDs, FOR UPDATE, document/item matching, unit_rate, quantity and all workflow writes remain Main unchanged.'),
('Inbound metadata transport','Builds exactly the existing Filter with same source/status/keyword/bill/date/warehouse/view/column criteria and uses PageMetadataRequest solely to select list(filter,false). Controller authorization annotations and export/write endpoints untouched; service remains responsible for ACL and exact selected total.'),
('Outbound metadata transport','Same bounded requested Filter, warehouse scope and column search; metadata parameter selects rows-only overload with existing metadata-included default. Authorization and business commands unchanged.'),
('Warehouse export continuation','Only chooses existing list(paged,false), skipping repeated summary/facets. Retains page1 declared-total maxRows check, internal100 row batch,2000 loop guard, per-loop budget checkpoints, row identities/order and truncation/maxRows protections. No write limit changed.'),
('Shipment rate test precision','Replaces formatted PostgreSQL numeric text concatenation comparisons with typed event record plus exact BigDecimal.compareTo. Still asserts release/revoke event order/type/source, explicit first1/2 sizes, NULL revoked rate/source, frozen expected rates, later business precision and permission scenarios. No production change or precision tolerance introduced.'),
('AI people security test','Adds people-page boundary regression: ordinary and impersonating superAdmin forbidden before dashboard interaction, genuine superAdmin bounded1/100 allowed, sessions untouched. Existing tests unchanged.'),
('Procurement queue predicate test','Adds RETURNED/HISTORY parameter cases verifying exact same narrow predicate across rows/count/facets/type-count; excludes WHERE TRUE and retains ALL normalization. Existing readonly/latest approval assertions unchanged.'),
('Fulfillment projection test','Adds positive/negative keyword placement checks, difference filter/sort preselection requirement and continuation total/capabilities/JSON-null metadata tests; existing export/source/ACL/difference tests retained unchanged. Aligns real SQL optimization with existing exact row contract.'),
('Warehouse output test','Changes mock to actual list(any,false) metadata overload and explicitly verifies old overload never called. Retains two equal-content but distinct line identities and exact selected output row integrity assertions; does not deduplicate rows or weaken identity.'),
('Legacy migration safety test','Replaces integer-only history SQL literal expectation with actual compound/raw-version loader protocol checks, Guard dependency and bounded source-git batch. Retains inventory/header/cmp/systemIdentifier/approval gates and asserts old int casts absent. Filename quote style expectation becomes filename-token-only; Python81 separately asserts actual controlled crosswalk membership. Original static quote failure preserved, not relabelled.')]
assert len(inputs['rows'])==len(notes)==14
for row,(title,note) in zip(inputs['rows'],notes):
    assert hashlib.sha256((root/row['path']).read_bytes()).hexdigest()==row['taskSha256']
    for key,sha in [('mainRaw','mainSha256'),('taskRaw','taskSha256'),('diffPath','diffSha256')]:assert hashlib.sha256((root/row[key]).read_bytes()).hexdigest()==row[sha]
    row.update({'reviewTitle':title,'reviewedChangedBlocks':True,'semanticReview':note,'staticIntegrationDecision':'Retain current candidate exact reviewed bytes; no hidden fifth semantic override. Runtime acceptance is separate and still pending.'})
support=['server/src/main/java/com/uten/imp/features/operations/workbench/FulfillmentWorkbenchPageRead.java','server/src/main/java/com/uten/imp/features/operations/workbench/FulfillmentWorkbenchTableQuery.java','server/src/main/java/com/uten/imp/features/finance/procurement/ProcurementOrderApprovalPredicates.java','server/src/main/java/com/uten/imp/features/finance/procurement/ProcurementOrderApprovalRead.java','server/src/main/resources/db/migration/V926__imported_business_documents_archive_only.sql','server/src/main/resources/db/migration/V933__deduplicate_imported_document_ancestry_walk.sql']
result={**inputs,'reviewedAtUtc':datetime.now(timezone.utc).isoformat(),'scope':'All actual14 server entries from integration needsReview, eight production and six tests. Exact Main/Task/diff raw snapshots plus manual changed-block and owning-contract review. No source/Main writes or CAS authorization inferred.','sourceAggregateSha256':json.loads((base/'complete-source-input.json').read_text(encoding='utf-8'))['aggregateSha256'],'supportingSourceSha256':{p:hashlib.sha256((root/p).read_bytes()).hexdigest() for p in support},'staticBlockers':[],'runtimeGreenClaimed':False,'mainWritten':False,'fourPathSemanticAllowlistExpanded':False}
(folder/'semantic-review.json').write_text(json.dumps(result,ensure_ascii=False,indent=2)+'\n',encoding='utf-8');print(json.dumps({'paths':len(result['rows']),'staticBlockers':result['staticBlockers'],'source':result['sourceAggregateSha256'],'reviewSha256':hashlib.sha256((folder/'semantic-review.json').read_bytes()).hexdigest()}))
